package GUI;
import Program.enums.IncomeCategory; import Program.model.*; import Program.service.IncomeService; import javafx.beans.property.SimpleStringProperty; import javafx.collections.*; import javafx.collections.transformation.FilteredList; import javafx.scene.control.*; import javafx.scene.layout.*; import java.time.LocalDate; import java.util.Arrays;
public class IncomeUI extends ScrollPane {private final User user;private final IncomeService service=new IncomeService();private final TableView<Income> table=new TableView<>();private final ObservableList<Income> source=FXCollections.observableArrayList();private final FilteredList<Income> filtered=new FilteredList<>(source,i->true);
 public IncomeUI(User user,MainUI app){this.user=user;setFitToWidth(true);VBox p=UIFactory.page("Income","Manage your earnings and other incoming money.");TextField search=UIFactory.field("Search description or category");ComboBox<String>category=new ComboBox<>();category.getItems().add("All categories");category.getItems().addAll(Arrays.stream(IncomeCategory.values()).map(IncomeCategory::getLabel).toList());category.setValue("All categories");Button add=UIFactory.button("+ Add Income","primary-button");HBox f=new HBox(10,search,category,add);HBox.setHgrow(search,Priority.ALWAYS);setup();refresh();Runnable filter=()->filtered.setPredicate(i->(search.getText().isBlank()||(i.getDescription()+" "+i.getCategory()).toLowerCase().contains(search.getText().toLowerCase()))&&(category.getValue().equals("All categories")||i.getCategory().equals(category.getValue())));search.textProperty().addListener((o,a,b)->filter.run());category.valueProperty().addListener((o,a,b)->filter.run());add.setOnAction(e->edit(null));p.getChildren().addAll(f,table);setContent(p);}
 private void setup(){table.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_NEXT_COLUMN);column("Date",i->i.getDate().toString());column("Category",Income::getCategory);column("Description",Income::getDescription);column("Amount",i->String.format("+ ৳%,.0f",i.getAmount()));TableColumn<Income,Void>a=new TableColumn<>("Actions");a.setCellFactory(c->new TableCell<>(){final Button edit=UIFactory.button("Edit","secondary-button"),delete=UIFactory.button("Delete","danger-button");final HBox buttons=new HBox(5,edit,delete);{edit.setOnAction(e->IncomeUI.this.edit(getTableView().getItems().get(getIndex())));delete.setOnAction(e->{Income income=getTableView().getItems().get(getIndex());if(new Alert(Alert.AlertType.CONFIRMATION,"Delete income?",ButtonType.YES,ButtonType.NO).showAndWait().orElse(ButtonType.NO)==ButtonType.YES){service.delete(income.getId());refresh();}});}@Override protected void updateItem(Void item,boolean empty){super.updateItem(item,empty);setGraphic(empty?null:buttons);}});table.getColumns().add(a);table.setItems(filtered);}private void column(String title,java.util.function.Function<Income,String>value){TableColumn<Income,String>c=new TableColumn<>(title);c.setCellValueFactory(x->new SimpleStringProperty(value.apply(x.getValue())));table.getColumns().add(c);}private void refresh(){source.setAll(service.loadIncomes(user.getId()));}
 private void edit(Income old){Dialog<ButtonType>d=new Dialog<>();d.setTitle(old==null?"Add Income":"Edit Income");TextField amount=UIFactory.field("Amount"),description=UIFactory.field("Optional description");ComboBox<String>cat=new ComboBox<>();cat.getItems().addAll(Arrays.stream(IncomeCategory.values()).map(IncomeCategory::getLabel).toList());DatePicker date=new DatePicker(LocalDate.now());if(old!=null){amount.setText(String.valueOf(old.getAmount()));cat.setValue(old.getCategory());date.setValue(old.getDate());description.setText(old.getDescription());}GridPane form=new GridPane();form.setHgap(10);form.setVgap(10);form.addRow(0,new Label("Amount"),amount);form.addRow(1,new Label("Category"),cat);form.addRow(2,new Label("Date"),date);form.addRow(3,new Label("Description"),description);d.getDialogPane().setContent(form);d.getDialogPane().getButtonTypes().addAll(ButtonType.CANCEL,ButtonType.OK);d.showAndWait().filter(x->x==ButtonType.OK).ifPresent(x->{try{if(cat.getValue()==null)throw new IllegalArgumentException("Please select a category.");double value=Program.utils.Validator.positiveAmount(amount.getText());if(old==null)service.add(user.getId(),value,cat.getValue(),date.getValue(),description.getText());else service.update(old,value,cat.getValue(),date.getValue(),description.getText());refresh();}catch(Exception ex){UIFactory.error(ex.getMessage());}});}
}
